u32 bch2_snapshot_tree_oldest_subvol(struct bch_fs *c, u32 snapshot_root)
{
	u32 id = snapshot_root;
	u32 subvol = 0;
	const struct snapshot_t *s;

	rcu_read_lock();
	while (id) {
		s = snapshot_t(c, id);
		if (!s)
			break;

		if (s->subvol && (!subvol || s->subvol < subvol))
			subvol = s->subvol;

		id = bch2_snapshot_tree_next(c, id);
	}
	rcu_read_unlock();

	return subvol;
}

